(async function () { const state = { user: {}, projects: [], filteredProjects: [] }; const selectors = { projectGrid: document.querySelector("#project-grid"), skillGrid: document.querySelector("#skill-grid"), timeline: document.querySelector("#timeline"), contactLinks: document.querySelector("#contact-links"), search: document.querySelector("#project-search"), language: document.querySelector("#language-filter") }; function getPathValue(source, path) { return path.split(".").reduce((value, key) => value?.[key], source); } async function fetchJson(path, fallback) { try { const response = await fetch(path, { cache: "no-store" }); if (!response.ok) throw new Error(`${path} returned ${response.status}`); return await response.json(); } catch (error) { console.warn(error); return fallback; } } function bindText() { document.querySelectorAll("[data-bind]").forEach((element) => { const value = getPathValue(state, element.dataset.bind); element.textContent = value || ""; }); document.querySelectorAll("[data-attr]").forEach((element) => { element.dataset.attr.split(",").forEach((binding) => { const [attribute, path] = binding.split(":"); const value = getPathValue(state, path); if (value) element.setAttribute(attribute, value); }); }); document.querySelectorAll("[data-attr*='href:']").forEach((element) => { if (!element.getAttribute("href") || element.getAttribute("href") === "#") { element.hidden = true; } }); document.querySelectorAll("img[data-attr*='src:']").forEach((element) => { if (!element.getAttribute("src")) { element.hidden = true; } }); } function updateSeo() { const title = state.user.name ? `${state.user.name} - ${state.user.role || "Portfolio"}` : "Portfolio"; const description = state.user.tagline || "Portfolio professionnel synchronise avec GitHub."; const url = window.location.href.split("#")[0]; const image = state.user.avatarUrl || ""; document.title = title; setMeta("description", description); setMeta("property", "og:title", title); setMeta("property", "og:description", description); setMeta("property", "og:image", image); setMeta("name", "twitter:title", title); setMeta("name", "twitter:description", description); setMeta("name", "twitter:image", image); document.querySelector("#json-ld").textContent = JSON.stringify({ "@context": "https://schema.org", "@type": "Person", name: state.user.name || "", jobTitle: state.user.role || "", url, image, sameAs: (state.user.links || []).map((link) => link.url) }); } function setMeta(kind, key, value) { let element = document.querySelector(`meta[${kind}="${key}"]`); if (!element) { element = document.createElement("meta"); element.setAttribute(kind, key); document.head.appendChild(element); } element.setAttribute("content", value || ""); } function renderProjects(projects) { selectors.projectGrid.innerHTML = ""; if (!projects.length) { selectors.projectGrid.innerHTML = '<p class="empty-state">Aucun projet a afficher. Ajoute le topic configure dans tes depots GitHub puis lance la synchronisation.</p>'; return; } projects.forEach((project) => { const card = document.createElement("article"); card.className = "project-card reveal"; card.innerHTML = ` <div class="project-meta"> ${project.language ? `<span class="language-dot">${escapeHtml(project.language)}</span>` : ""} <span>${Number(project.stars || 0)} etoile(s)</span> ${project.updatedAt ? `<span>MAJ ${new Date(project.updatedAt).toLocaleDateString("fr-FR")}</span>` : ""} </div> <h3>${escapeHtml(project.name || project.title || "Projet")}</h3> <p>${escapeHtml(project.description || "Description a renseigner dans GitHub ou data/projects.json.")}</p> <div class="tag-list">${(project.topics || []).slice(0, 5).map((topic) => `<span class="tag">${escapeHtml(topic)}</span>`).join("")}</div> <div class="card-actions"> ${project.url ? `<a class="button ghost" href="${project.url}" target="_blank" rel="noreferrer">Code</a>` : ""} ${project.homepage ? `<a class="button primary" href="${project.homepage}" target="_blank" rel="noreferrer">Demo</a>` : ""} </div> `; selectors.projectGrid.appendChild(card); }); observeReveals(); } function renderLanguageFilter() { const languages = [...new Set(state.projects.map((project) => project.language).filter(Boolean))].sort(); languages.forEach((language) => { const option = document.createElement("option"); option.value = language; option.textContent = language; selectors.language.appendChild(option); }); } function applyProjectFilters() { const query = selectors.search.value.trim().toLowerCase(); const language = selectors.language.value; state.filteredProjects = state.projects.filter((project) => { const searchable = [ project.name, project.description, project.language, ...(project.topics || []) ].join(" ").toLowerCase(); return (!language || project.language === language) && (!query || searchable.includes(query)); }); renderProjects(state.filteredProjects); } function renderSkills() { selectors.skillGrid.innerHTML = ""; (state.user.skills || []).forEach((group) => { const element = document.createElement("article"); element.className = "skill-group reveal"; element.innerHTML = ` <h3>${escapeHtml(group.category)}</h3> <div class="skill-list">${(group.items || []).map((item) => `<span class="tag">${escapeHtml(item)}</span>`).join("")}</div> `; selectors.skillGrid.appendChild(element); }); } function renderTimeline() { selectors.timeline.innerHTML = ""; (state.user.experience || []).forEach((item) => { const element = document.createElement("article"); element.className = "timeline-item reveal"; element.innerHTML = ` <time>${escapeHtml(item.period || "")}</time> <h3>${escapeHtml(item.title || "")}</h3> <p>${escapeHtml(item.description || "")}</p> `; selectors.timeline.appendChild(element); }); } function renderLinks() { selectors.contactLinks.innerHTML = ""; (state.user.links || []).forEach((link) => { const anchor = document.createElement("a"); anchor.className = "button ghost"; anchor.href = link.url; anchor.target = "_blank"; anchor.rel = "noreferrer"; anchor.textContent = link.label; selectors.contactLinks.appendChild(anchor); }); } function escapeHtml(value) { return String(value || "").replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" })[character]); } function setupTheme() { const savedTheme = localStorage.getItem("theme"); const prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches; document.documentElement.dataset.theme = savedTheme || (prefersDark ? "dark" : "light"); document.querySelector("#theme-toggle").addEventListener("click", () => { const nextTheme = document.documentElement.dataset.theme === "dark" ? "light" : "dark"; document.documentElement.dataset.theme = nextTheme; localStorage.setItem("theme", nextTheme); }); } function setupHeader() { const header = document.querySelector(".site-header"); const update = () => header.dataset.elevated = String(window.scrollY > 8); update(); window.addEventListener("scroll", update, { passive: true }); } function observeReveals() { if (!("IntersectionObserver" in window)) { document.querySelectorAll(".reveal").forEach((element) => element.classList.add("is-visible")); return; } const observer = new IntersectionObserver((entries) => { entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add("is-visible"); observer.unobserve(entry.target); } }); }, { threshold: 0.12 }); document.querySelectorAll(".reveal:not(.is-visible)").forEach((element) => observer.observe(element)); } function setupFilters() { selectors.search.addEventListener("input", applyProjectFilters); selectors.language.addEventListener("change", applyProjectFilters); } async function init() { setupTheme(); setupHeader(); state.user = await fetchJson("data/user.json", {}); state.projects = await window.PortfolioGithubSync.loadProjects("data/projects.json"); if (!state.projects.length && state.user.liveGithubSync) { try { state.projects = await window.PortfolioGithubSync.fetchPortfolioRepositories( state.user.githubUsername, state.user.portfolioTopic || "portfolio" ); } catch (error) { console.warn(error); } } state.filteredProjects = state.projects; bindText(); updateSeo(); renderLanguageFilter(); renderProjects(state.projects); renderSkills(); renderTimeline(); renderLinks(); setupFilters(); observeReveals(); document.querySelector("#footer-year").textContent = new Date().getFullYear(); } init(); })();
